 s=importlib.util.spec_from_file_location('prep',ROOT/'docs/review/prepared-replay.py');prep=importlib.util.module_from_spec(s);s.loader.exec_module(prep);n=prep.load('native',ROOT/'docs/review/native-smoke-replay.py');base=Path(tempfile.mkdtemp(prefix='merged-external-',dir=ROOT/'.tmp'))
 libsource='namespace Shared.Other\ntype Person = { Name: string }\n';lib=n.fixture(base,'library',{'Library.fs':libsource});(lib/'Test.fsproj').rename(lib/'External.fsproj');report={'binarySha256':hashlib.sha256(a.binary.read_bytes()).hexdigest(),'helperSha256':hashlib.sha256(prep.HELPER.read_bytes()).hexdigest(),'fixtureRoot':str(base),'sources':{'Library.fs':libsource},'builds':[prep.build(lib/'External.fsproj')],'provenance':'Real external library and consumer build; executable prints the selected parameter nominal assembly. The opened namespace has both source and external contributions.'};dll=lib/'bin/Debug/net10.0/External.dll'
